// Junta os resultados de todas as consultas (Prometheus + Loki) num só
// objeto e monta o relatório executivo em HTML (depois convertido pra PDF
// pelo node Gotenberg). Todas as consultas rodam em CADEIA (uma depois da
// outra), não em paralelo -- é o que garante que este node só executa UMA
// vez, com todos os dados já prontos (antes disparava 1x por consulta que
// chegava, gerando e-mails parciais).
function firstValue(nodeName) {
  try {
    const result = $(nodeName).first().json.data.result;
    if (!result || !result.length) return null;
    return parseFloat(result[0].value[1]);
  } catch (e) {
    return null;
  }
}

function topEndpoints(nodeName) {
  try {
    const result = $(nodeName).first().json.data.result;
    if (!result || !result.length) return [];
    return result
      .map(r => ({ view: r.metric.view || '(sem nome)', count: parseFloat(r.value[1]) }))
      .sort((a, b) => b.count - a.count);
  } catch (e) {
    return [];
  }
}

const cfg = $('Configuração').first().json;

const uptime = firstValue('Uptime');
const totalRequests = firstValue('Requisições totais');
const totalErrors = firstValue('Erros 5xx totais');
const p95 = firstValue('Latência p95 média');
const errorLogLines = firstValue('Linhas de log de erro');
const topEnds = topEndpoints('Top 3 endpoints');

const fmtInt = (v) => (v === null || Number.isNaN(v)) ? '-' : Math.round(v).toLocaleString('pt-BR');
const fmtPct = (v) => (v === null || Number.isNaN(v)) ? '-' : v.toFixed(2).replace('.', ',') + '%';
const fmtMs = (v) => (v === null || Number.isNaN(v)) ? '-' : Math.round(v * 1000).toLocaleString('pt-BR') + ' ms';

const errorRate = (totalRequests && totalErrors !== null && totalRequests > 0)
  ? (totalErrors / totalRequests) * 100
  : 0;

const now = new Date();
const firstDay = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const lastDay = new Date(now.getFullYear(), now.getMonth(), 0);
const monthLabel = firstDay.toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' });
const periodLabel = `${firstDay.getDate()} a ${lastDay.getDate()} de ${firstDay.toLocaleDateString('pt-BR', { month: 'long' })} de ${firstDay.getFullYear()}`;

const accent = cfg.client_primary_color || '#0EA5E9';
const uptimeOk = uptime === null || uptime >= 99.5;
const errorsOk = errorRate < 1;

const topEndpointsRows = topEnds.length
  ? topEnds.map((e, i) => `
    <tr>
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;color:#6b7280;font-size:13px;">${i + 1}º</td>
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;font-size:13px;font-weight:600;color:#111827;">${e.view}</td>
      <td style="padding:10px 12px;border-bottom:1px solid #e5e7eb;font-size:13px;color:#111827;text-align:right;">${fmtInt(e.count)} acessos</td>
    </tr>`).join('')
  : `<tr><td colspan="3" style="padding:10px 12px;color:#6b7280;font-size:13px;">Sem dados suficientes neste período.</td></tr>`;

const topEndpointName = topEnds.length ? topEnds[0].view : 'nenhum em destaque';
const topEndpointCount = topEnds.length ? fmtInt(topEnds[0].count) : '-';

const summary = `Durante o período de ${periodLabel}, a aplicação de <strong>${cfg.client_name}</strong> processou <strong>${fmtInt(totalRequests)} requisições</strong>, `
  + `com <strong>${fmtPct(uptime)} de disponibilidade</strong>`
  + (errorsOk ? ' e sem nenhum problema técnico relevante registrado.' : `, e uma taxa de erros de ${fmtPct(errorRate)} que merece atenção.`)
  + ` O recurso mais utilizado no período foi <strong>${topEndpointName}</strong>, com ${topEndpointCount} acessos.`;

const html = `<!doctype html>
<html lang="pt-br">
<head>
<meta charset="utf-8">
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Arial, sans-serif;
    color: #111827;
    background: #ffffff;
    font-size: 14px;
    line-height: 1.6;
  }
  .page { padding: 48px 56px; max-width: 800px; margin: 0 auto; }
  .header {
    display: flex; align-items: center; gap: 16px;
    padding-bottom: 24px; margin-bottom: 32px;
    border-bottom: 3px solid ${accent};
  }
  .header img { height: 40px; width: auto; }
  .header .title { font-size: 20px; font-weight: 700; color: #111827; }
  .header .subtitle { font-size: 13px; color: #6b7280; margin-top: 2px; text-transform: capitalize; }
  .summary {
    background: #f9fafb; border: 1px solid #e5e7eb; border-left: 4px solid ${accent};
    border-radius: 6px; padding: 20px 24px; margin-bottom: 32px; font-size: 14.5px; color: #1f2937;
  }
  .summary .eyebrow { font-size: 11px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: ${accent}; margin-bottom: 8px; }
  .metrics-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 32px; }
  .metric-card { border: 1px solid #e5e7eb; border-radius: 8px; padding: 18px 20px; }
  .metric-card .label { font-size: 11px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: #6b7280; }
  .metric-card .value { font-size: 28px; font-weight: 700; color: #111827; margin: 6px 0 8px; }
  .metric-card .explain { font-size: 12.5px; color: #6b7280; }
  .badge { display: inline-block; font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 999px; margin-left: 8px; vertical-align: middle; }
  .badge.ok { background: #dcfce7; color: #166534; }
  .badge.warn { background: #fef3c7; color: #92400e; }
  .section-title { font-size: 15px; font-weight: 700; margin: 32px 0 12px; color: #111827; }
  table { width: 100%; border-collapse: collapse; }
  th { text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: #6b7280; padding: 8px 12px; border-bottom: 2px solid #e5e7eb; }
  .footer { margin-top: 40px; padding-top: 20px; border-top: 1px solid #e5e7eb; font-size: 11px; color: #9ca3af; display: flex; justify-content: space-between; }
</style>
</head>
<body>
<div class="page">

  <div class="header">
    <img src="${cfg.client_logo_url}" alt="${cfg.client_name}">
    <div>
      <div class="title">${cfg.client_name}</div>
      <div class="subtitle">Relatório mensal de performance &mdash; ${monthLabel}</div>
    </div>
  </div>

  <div class="summary">
    <div class="eyebrow">Resumo executivo</div>
    ${summary}
  </div>

  <div class="metrics-grid">
    <div class="metric-card">
      <div class="label">Disponibilidade${uptimeOk ? '<span class="badge ok">saudável</span>' : '<span class="badge warn">atenção</span>'}</div>
      <div class="value">${fmtPct(uptime)}</div>
      <div class="explain">Percentual do tempo em que a aplicação ficou no ar e respondendo normalmente. 100% significa nenhuma interrupção detectada no período.</div>
    </div>
    <div class="metric-card">
      <div class="label">Volume de uso</div>
      <div class="value">${fmtInt(totalRequests)}</div>
      <div class="explain">Total de requisições (acessos) recebidas pela aplicação no período &mdash; um indicador direto de quanto a ferramenta foi usada.</div>
    </div>
    <div class="metric-card">
      <div class="label">Taxa de erros${errorsOk ? '<span class="badge ok">saudável</span>' : '<span class="badge warn">atenção</span>'}</div>
      <div class="value">${fmtPct(errorRate)}</div>
      <div class="explain">Percentual de requisições que resultaram em falha técnica no servidor. Quanto mais perto de 0%, melhor.</div>
    </div>
    <div class="metric-card">
      <div class="label">Tempo de resposta</div>
      <div class="value">${fmtMs(p95)}</div>
      <div class="explain">Tempo médio que a aplicação leva pra responder a uma solicitação. Valores baixos indicam boa performance percebida pelo usuário.</div>
    </div>
  </div>

  <div class="section-title">Recursos mais utilizados no período</div>
  <table>
    <thead><tr><th>#</th><th>Recurso</th><th style="text-align:right;">Uso</th></tr></thead>
    <tbody>${topEndpointsRows}</tbody>
  </table>

  <div class="section-title">Outros indicadores</div>
  <table>
    <tbody>
      <tr><td style="padding:8px 12px;border-bottom:1px solid #e5e7eb;color:#6b7280;font-size:13px;">Linhas de log de erro registradas</td><td style="padding:8px 12px;border-bottom:1px solid #e5e7eb;text-align:right;font-weight:600;">${fmtInt(errorLogLines)}</td></tr>
    </tbody>
  </table>

  <div class="footer">
    <span>Relatório gerado automaticamente por Arcus Cloud Security</span>
    <span>${periodLabel}</span>
  </div>

</div>
</body>
</html>`;

return [{
  json: {
    subject: `Relatório mensal — ${cfg.client_name} — ${monthLabel}`,
    html,
    to: cfg.client_email_to,
    month_label: monthLabel,
  }
}];

// O node HTTP Request de multipart do n8n usa o nome do CAMPO binário como
// nome de arquivo no multipart -- Gotenberg exige que o arquivo principal se
// chame exatamente "index.html". Preparamos o binário aqui com esse nome
// antes de chamar o Gotenberg.
const item = $input.first();
const buffer = Buffer.from(item.json.html, 'utf-8');
return [{
  json: item.json,
  binary: {
    report_html: {
      data: buffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html',
    },
  },
}];
